import {useLayoutEffect,useRef} from 'react';
import {FlatList,Text,View,type ViewProps} from 'react-native';
import {createStore} from 'zustand/vanilla';
import {useStore} from 'zustand';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {LiveRecordingWaveform,type LiveRecordingWaveformProps} from '@/components/nyc-tron/ui/components/forge/audio/LiveRecordingWaveform';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
export interface VoiceoverTake {id:string;label:string;durationSamples:number;saved:boolean}
export interface VoiceoverCountdownAndTakeBinProps extends Omit<ViewProps,'children'>,ScopedControlProps {
 status:'idle'|'countdown'|'recording'|'saving'|'error';countdownRemainingMs:number|null;
 permission:'unknown'|'granted'|'denied';input:LiveRecordingWaveformProps;takes:readonly VoiceoverTake[];selectedId:string|null;error?:string;
 onRequestPermission:(signal?:AbortSignal)=>unknown;onBeginCountdown:(signal?:AbortSignal)=>unknown;onCancelCountdown:()=>void;
 onStopAndSave:(signal?:AbortSignal)=>unknown;onSelect:(id:string)=>void;onAudition:(id:string,signal?:AbortSignal)=>unknown;
 onDiscard:(id:string,signal?:AbortSignal)=>unknown;onRetry:(signal?:AbortSignal)=>unknown;unstyled?:boolean;
}
/** Countdown follows native capture telemetry. Discard requires choosing a specific take and confirming it. */
export function VoiceoverCountdownAndTakeBin({scope='voiceover-takes',revision=0,...props}:VoiceoverCountdownAndTakeBinProps){
 const {status,countdownRemainingMs,permission,input,takes,selectedId,error,onRequestPermission:_permission,onBeginCountdown:_begin,onCancelCountdown,onStopAndSave:_stop,onSelect:_select,onAudition:_audition,onDiscard:_discard,onRetry:_retry,unstyled=false,disabledReason,style,...rest}=props;
 if(!['idle','countdown','recording','saving','error'].includes(status)||!['unknown','granted','denied'].includes(permission)||countdownRemainingMs!==null&&(!Number.isFinite(countdownRemainingMs)||countdownRemainingMs<0||countdownRemainingMs>600000)||takes.length>10000||new Set(takes.map(t=>t.id)).size!==takes.length||takes.some(t=>!t.id.trim()||t.id.length>512||!t.label.trim()||t.label.length>1024||!Number.isSafeInteger(t.durationSamples)||t.durationSamples<0))throw new RangeError('Invalid voiceover capture state');
 const identity=JSON.stringify(controlIdentity(scope,revision)),owner=JSON.stringify([identity,status,disabledReason]),guard=useScopedControl(owner,props,disabledReason!==undefined||status==='recording'||status==='saving'||status==='countdown'),stop=useScopedControl(identity,props),off=guard.pending||disabledReason!==undefined||status==='recording'||status==='saving'||status==='countdown';
 const local=useRef<ReturnType<typeof makeStore>|null>(null);local.current??=makeStore();const store=local.current,discardId=useStore(store,s=>s.discardId);
 useLayoutEffect(()=>{store.setState({discardId:null});},[identity,status]);
 const discard=takes.find(t=>t.id===discardId);
 return <View {...rest} accessibilityLabel="Voiceover recording and takes" style={[{gap:8},style]}>
  <Text accessibilityLiveRegion="assertive" {...{className:unstyled?undefined:'text-text'}}>{status==='countdown'?`Recording starts in ${countdownRemainingMs===null?'time not reported':Math.ceil(countdownRemainingMs/1000)+' seconds'}`:`Voiceover ${status}`}</Text>
  <LiveRecordingWaveform {...input} unstyled={unstyled}/>
  {permission!=='granted'?<Button title="Review microphone permission" disabled={off} unstyled={unstyled} onPress={()=>guard.run('permission',(h,s)=>h.onRequestPermission(s))}/>:null}
  <Button title="Start voiceover countdown" disabled={off||permission!=='granted'} unstyled={unstyled} onPress={()=>guard.run('begin',(h,s)=>h.permission==='granted'?h.onBeginCountdown(s):undefined)}/>
  {status==='countdown'||guard.pendingId==='begin'?<Button title="Cancel voiceover countdown" variant="secondary" unstyled={unstyled} onPress={()=>{if(guard.cancel())onCancelCountdown();}}/>:null}
  {status==='recording'?<Button title="Stop and save voiceover take" disabled={stop.pending} unstyled={unstyled} onPress={()=>stop.run('save',(h,s)=>h.status==='recording'?h.onStopAndSave(s):undefined)}/>:null}
  <FlatList data={takes} keyExtractor={t=>t.id} style={{height:320}} initialNumToRender={6} windowSize={5} extraData={[off,selectedId]} ListEmptyComponent={<Text {...{className:unstyled?undefined:'text-text'}}>No voiceover takes supplied</Text>} renderItem={({item})=><View style={{gap:6,paddingVertical:8}}><Button title={`${item.label} · ${(item.durationSamples/input.sampleRate).toFixed(2)} s · ${item.saved?'saved':'unsaved'}`} accessibilityState={{selected:item.id===selectedId}} disabled={off} unstyled={unstyled} onPress={()=>guard.current()?.onSelect(item.id)}/><View style={{flexDirection:'row',flexWrap:'wrap',gap:6}}><Button title={'Audition '+item.label} disabled={off} unstyled={unstyled} onPress={()=>guard.run('audition',(h,s)=>h.takes.some(t=>t.id===item.id)?h.onAudition(item.id,s):undefined)}/><Button title={'Discard '+item.label} variant="danger" disabled={off} unstyled={unstyled} onPress={()=>store.setState({discardId:item.id})}/></View></View>}/>
  {discard?<View accessibilityLabel="Confirm take discard" style={{gap:6}}><Text {...{className:unstyled?undefined:'text-text'}}>Discard {discard.label}? This removes the recorded take.</Text><Button title="Confirm discard take" variant="danger" disabled={off} unstyled={unstyled} onPress={()=>guard.run('discard',async(h,s)=>{if(!h.takes.some(t=>t.id===discard.id))return;await h.onDiscard(discard.id,s);store.setState({discardId:null});})}/><Button title="Keep take" variant="secondary" unstyled={unstyled} onPress={()=>store.setState({discardId:null})}/></View>:null}
  {status==='error'?<Button title="Retry voiceover recording" disabled={off} unstyled={unstyled} onPress={()=>guard.run('retry',(h,s)=>h.onRetry(s))}/>:null}
  <ErrorMessage message={guard.error??stop.error??error??disabledReason} unstyled={unstyled}/>
 </View>;
}
function makeStore(){return createStore(()=>({discardId:null as string|null}));}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}
